using UnityEngine; using UnityEngine.SceneManagement; using UnityEngine.UI; using System.Collections;
public class StreetLegendMainMenu:MonoBehaviour{
 Canvas canvas;Text status;bool busy;
 void Awake(){Screen.orientation=ScreenOrientation.LandscapeLeft;Time.timeScale=1;BuildUI();}
 void BuildUI(){var root=new GameObject("Street Legend Menu Canvas",typeof(RectTransform),typeof(Canvas),typeof(CanvasScaler),typeof(GraphicRaycaster));canvas=root.GetComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceOverlay;canvas.sortingOrder=10;var sc=root.GetComponent<CanvasScaler>();sc.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;sc.referenceResolution=new Vector2(1920,1080);sc.matchWidthOrHeight=.5f;var p=Panel(root.transform,"Menu Backdrop",new Vector2(.5f,.5f),new Vector2(1100,820),new Color(.025f,.06f,.12f,.92f));Txt(p.transform,"STREET LEGEND",new Vector2(.5f,.78f),new Vector2(820,150),70,Color.white);Txt(p.transform,"LEONIDA • FIGHT FOR YOUR STORY",new Vector2(.5f,.65f),new Vector2(820,80),28,new Color(.2f,.78f,.95f));Btn(p.transform,"PLAY CAMPAIGN",new Vector2(.5f,.50f),Launch,true);Btn(p.transform,"SETTINGS",new Vector2(.5f,.32f),Settings,false);Btn(p.transform,"QUIT",new Vector2(.5f,.16f),()=>Application.Quit(),false);status=Txt(p.transform,"",new Vector2(.5f,.015f),new Vector2(900,45),22,new Color(.7f,.8f,.9f));}
 void Launch(){if(busy)return;busy=true;StartCoroutine(LoadMission());} IEnumerator LoadMission(){status.text="PREPARING HOTEL DISTRICT...";yield return new WaitForSecondsRealtime(.7f);var op=SceneManager.LoadSceneAsync("Level1_Hotel_Prototype");while(!op.isDone){status.text="LOADING...";yield return null;}}
 void Settings(){bool v=PlayerPrefs.GetInt("SL_VOICE",1)==1;bool s=PlayerPrefs.GetInt("SL_SUBS",0)==1;PlayerPrefs.SetInt("SL_VOICE",v?0:1);PlayerPrefs.SetInt("SL_SUBS",s?1:0);PlayerPrefs.Save();status.text="VOICE "+(v?"OFF":"ON")+" • SUBTITLES "+(s?"ON":"OFF")+" — use HUD toggles in combat too";}
 GameObject Panel(Transform par,string n,Vector2 a,Vector2 size,Color c){var g=new GameObject(n,typeof(RectTransform),typeof(Image));g.transform.SetParent(par,false);var r=g.GetComponent<RectTransform>();r.anchorMin=a;r.anchorMax=a;r.sizeDelta=size;g.GetComponent<Image>().color=c;return g;}
 Text Txt(Transform par,string s,Vector2 a,Vector2 size,int fs,Color c){var g=new GameObject(s+" Text",typeof(RectTransform),typeof(Text));g.transform.SetParent(par,false);var r=g.GetComponent<RectTransform>();r.anchorMin=a;r.anchorMax=a;r.sizeDelta=size;var t=g.GetComponent<Text>();t.font=Resources.GetBuiltinResource<Font>("Arial.ttf");t.text=s;t.fontSize=fs;t.fontStyle=FontStyle.Bold;t.alignment=TextAnchor.MiddleCenter;t.color=c;t.raycastTarget=false;return t;}
 void Btn(Transform par,string s,Vector2 a,UnityEngine.Events.UnityAction act,bool primary){var g=Panel(par,s+" Button",a,new Vector2(620,84),primary?new Color(.08f,.48f,.72f):new Color(.1f,.18f,.27f));g.AddComponent<Button>().onClick.AddListener(act);Txt(g.transform,s,new Vector2(.5f,.5f),new Vector2(580,72),30,Color.white);}
}